<template>
  <div class="flex-direction-column">
    <div
      class="g-page-container-with-header"
      v-for="imu in sortedImuData"
      :key="imu.devid"
    >
      <div class="container-header flex-space-between">
        <span class="title">IMU {{ imu.devid }}</span>
        <div class="g-button" @click="handleRefreshRow(imu)">更新</div>
      </div>
      <div class="container-content">
        <div class="g-double-column-layout">
          <div class="column">
            <div
              class="g-kv-pair"
              v-for="(label, key) in section1Labels"
              :key="key"
            >
              <div class="label">{{ label }}</div>
              <div
                class="value"
                :style="
                  key === 'status'
                    ? getStatusTextStyle(getSection1Value(imu, key))
                    : {}
                "
              >
                {{ getSection1Value(imu, key) }}
              </div>
            </div>
          </div>
          <div class="column">
            <div
              class="g-kv-pair"
              v-for="(label, key) in section2Labels"
              :key="key"
            >
              <div class="label">{{ label }}</div>
              <div class="value">{{ getSection2Value(imu, key) }}</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed, watch } from 'vue'
import { storeToRefs } from 'pinia'
import { useWslStore } from '@/store/modules/ws.js'
import { useCommand } from '@/hooks/useCommand.js'
import { useDataMerge } from '@/hooks/useDataMerge'
import { useTimeFormat } from '@/hooks/useTimeFormat'
const { formatTimestamp } = useTimeFormat()

const store = useWslStore()
const { received, isConnected } = storeToRefs(store)
const { sendGetStatusData } = useCommand(store)

import { useStatus } from '@/hooks/useStatus'
const { getStatusTextStyle } = useStatus()

import { useSortData } from '@/hooks/useSortData'

// 标签定义
const section1Labels = {
  devid: '设备ID',
  devname: '设备名称',
  devtype: '设备类型',
  devdesp: '设备描述',
  status: '状态',
  timestamp: '时间',
  freq: '频率'
}

const section2Labels = {
  orientationXYZW: '朝向（X, Y, Z, W）',
  angularXYZ: '角度（X, Y, Z）',
  accelerationXYZ: '线加速度（X, Y, Z）',
  roll: '偏转角（roll）',
  pitch: '俯仰角（pitch）',
  yaw: '翻滚角（yaw）'
}

// 获取imu数据，兼容13和61命令
const imuData = useDataMerge(
  computed(() => {
    const data = received.value?.statusData?.imuDataList
    if (!data || data.length === 0) {
      return [
        {
          devdesp: '暂无'
        }
      ]
    }
    return data
  })
).mergedData

const sortedImuData = useSortData(imuData, {
  key: 'devid',
  type: 'number',
  order: 'asc'
}).sortedData

// 第一组值的获取
const getSection1Value = (item, key) => {
  let value = item[key]
  if (key === 'timestamp' && value) {
    value = formatTimestamp(value)
  }
  return value === null || value === undefined || value === '' ? '-' : value
}

// 第二组值的获取
const getSection2Value = (imu, key) => {
  // 判断单个值是否为空
  const formatValue = (value, unit = '') => {
    return value === null || value === undefined || value === ''
      ? '-'
      : `${value.toFixed(2)}${unit}`
  }

  switch (key) {
    case 'orientationXYZW':
      return `${formatValue(imu.orientationX)}, ${formatValue(
        imu.orientationY
      )}, ${formatValue(imu.orientationZ)}, ${formatValue(imu.orientationW)}`

    case 'angularXYZ':
      return `${formatValue(imu.angularVelocityX)}, ${formatValue(
        imu.angularVelocityY
      )}, ${formatValue(imu.angularVelocityZ)} °/s`

    case 'accelerationXYZ':
      return `${formatValue(imu.linearAccelerationX)}, ${formatValue(
        imu.linearAccelerationY
      )}, ${formatValue(imu.linearAccelerationZ)} m/s²`

    case 'roll':
      return formatValue(imu.roll, '°')

    case 'pitch':
      return formatValue(imu.pitch, '°')

    case 'yaw':
      return formatValue(imu.yaw, '°')

    default:
      return '-'
  }
}

// 单行刷新处理
const handleRefreshRow = (item) => {
  if (item.devid) {
    sendGetStatusData('imu', item.devid)
  }
}

// 等socket连接后发送13命令获取数据
watch(
  () => isConnected.value,
  (newStatus) => {
    if (newStatus) {
      sendGetStatusData('imu')
    }
  },
  { immediate: true }
)
</script>

<style lang="less" scoped></style>
